from __future__ import annotations


def _is_non_empty_string(value: object) -> bool:
    return isinstance(value, str) and value != ""


def _is_plain_integer(value: object) -> bool:
    return type(value) is int


def _is_indexable_purchase(event: dict) -> bool:
    return (
        event.get("kind") == "purchase"
        and _is_non_empty_string(event.get("user_id"))
        and _is_plain_integer(event.get("amount"))
    )


def _validate_events(events: list[dict]) -> None:
    if not isinstance(events, list):
        raise TypeError("events must be a list of dictionaries")

    for index, event in enumerate(events):
        if not isinstance(event, dict):
            raise TypeError(f"events[{index}] must be a dictionary")


def _validate_min_amount(min_amount: int) -> None:
    if type(min_amount) is not int:
        raise TypeError("min_amount must be an integer")

    if min_amount < 0:
        raise ValueError("min_amount must be non-negative")


def build_user_purchase_index(
    events: list[dict], *, min_amount: int = 0
) -> dict[str, dict[str, int]]:
    _validate_events(events)
    _validate_min_amount(min_amount)

    index: dict[str, dict[str, int]] = {}

    for event in events:
        if not _is_indexable_purchase(event):
            continue

        user_id = event["user_id"]
        amount = event["amount"]

        if amount < min_amount:
            continue

        if user_id not in index:
            index[user_id] = {"count": 0, "total": 0}

        index[user_id]["count"] += 1
        index[user_id]["total"] += amount

    return index

